// src/unified-paste-extension.ts
function fallbackInsert(editor, snapshot) {
  if (editor.isDestroyed) {
    return;
  }
  const plain = snapshot.textPlain;
  if (clipboardLooksLikeBlockMarkdown(plain)) {
    return;
  }
  const html2 = snapshot.textHtml.trim();
  const preferPlain = shouldPreferPlainTextBody(plain, html2);
  if (html2 && !preferPlain) {
    const ok2 = editor.chain().focus().insertContent(html2, { parseOptions: { preserveWhitespace: "full" } }).run();
    if (ok2) {
      return;
    }
  }
  if (plain.trim()) {
    const normalized = normalizeClipboardNewlines(plain).replace(/\u00a0/g, " ");
    const body = normalized.split(/\n{2,}/).map((para) => {
      const inner = para.replace(/^\n+|\n+$/g, "");
      if (!inner) return "";
      const escaped = inner.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/\n/g, "<br>");
      return `<p>${escaped}</p>`;
    }).filter(Boolean).join("");
    if (body) {
      editor.chain().focus().insertContent(body, { parseOptions: { preserveWhitespace: "full" } }).run();
      return;
    }
    editor.chain().focus().insertContent(plain).run();
  }
}
function createUnifiedPasteExtension() {
  return Extension.create({
    name: "agnxNotesUnifiedPaste",
    // 高于旧 markdown(1200)/image(1300) 扩展，确保单入口
    priority: 1500,
    addProseMirrorPlugins() {
      const editor = this.editor;
      return [
        new Plugin({
          key: new PluginKey("agnxNotesUnifiedPaste"),
          props: {
            handlePaste: (_view, event) => {
              if (!editor.isEditable || editor.isDestroyed) {
                return false;
              }
              const browserSnapshot = snapshotClipboardData(event.clipboardData);
              const blockMarkdown = clipboardLooksLikeBlockMarkdown(browserSnapshot.textPlain);
              if (editor.isActive("codeBlock") && !blockMarkdown) {
                return false;
              }
              if (editor.isActive("codeBlock") && blockMarkdown) {
                prepareBlockMarkdownPaste(editor);
              }
              event.preventDefault();
              void (async () => {
                if (editor.isDestroyed) {
                  return;
                }
                const snapshot = await enrichClipboardSnapshot(browserSnapshot);
                if (shouldHandleUnifiedPaste(snapshot)) {
                  const ok2 = await runUnifiedRichPaste(editor, snapshot);
                  if (!ok2) {
                    fallbackInsert(editor, snapshot);
                  }
                  return;
                }
                fallbackInsert(editor, snapshot);
              })();
              return true;
            },
            handleDrop: (_view, event) => {
              if (!editor.isEditable || editor.isDestroyed) {
                return false;
              }
              const files = collectImageFilesFromDataTransfer(event.dataTransfer);
              if (files.length === 0) {
                return false;
              }
              event.preventDefault();
              const snapshot = {
                textPlain: "",
                textHtml: "",
                imageFiles: files,
                imageSrcHints: [],
                clipboardImages: []
              };
              void runUnifiedRichPaste(editor, snapshot);
              return true;
            }
          }
        })
      ];
    }
  });
}

