function jumpEditorToHeading(editor, heading3) {
  let matchPos = null;
  let fallbackPos = null;
  let occurrence = 0;
  const wantedOccurrence = Math.max(0, heading3.occurrence);
  editor.state.doc.descendants((node, pos2) => {
    if (node.type.name !== "heading") {
      return;
    }
    const text2 = node.textContent.trim();
    if (text2 !== heading3.text.trim()) {
      return;
    }
    if (node.attrs.level === heading3.level) {
      if (occurrence === wantedOccurrence) {
        matchPos = pos2;
        return false;
      }
      occurrence += 1;
      return;
    }
    if (fallbackPos == null) {
      fallbackPos = pos2;
    }
  });
  const pos = matchPos ?? fallbackPos;
  if (pos == null) {
    return false;
  }
  editor.chain().focus().setTextSelection(pos + 1).run();
  const dom = editor.view.nodeDOM(pos);
  const scrollRoot = editor.view.dom.closest(".agnx-notes-tiptap");
  if (!(dom instanceof HTMLElement)) {
    return false;
  }
  if (scrollRoot) {
    const rootRect = scrollRoot.getBoundingClientRect();
    const nodeRect = dom.getBoundingClientRect();
    const nextTop = scrollRoot.scrollTop + (nodeRect.top - rootRect.top) - 24;
    scrollRoot.scrollTo({ top: Math.max(0, nextTop), behavior: "smooth" });
  } else {
    dom.scrollIntoView({ behavior: "smooth", block: "start" });
  }
  return true;
}

